import { formatGenerated } from './generated-format.mjs';
import ts from 'typescript';
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const defaultRoot = fileURLToPath(new URL('../', import.meta.url));
const marker =
  '// Generated by scripts/generate-component-controls.mjs. Do not edit.';
const slug = (name) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1-$2')
    .toLowerCase();

/** Resolve each catalog control to its actual source export, without importing the catalog. */
export function componentControls(root = defaultRoot) {
  const packageRoot = resolve(root, 'package');
  const rawFile = resolve(packageRoot, 'preact-raw.ts');
  const catalogFile = resolve(packageRoot, 'component-catalog.ts');
  const stylesFile = resolve(packageRoot, 'preact.ts');
  const program = ts.createProgram([rawFile, catalogFile, stylesFile], {
    target: ts.ScriptTarget.ESNext,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    jsx: ts.JsxEmit.ReactJSX,
    jsxImportSource: 'preact',
    skipLibCheck: true,
  });
  const checker = program.getTypeChecker();
  const raw = program.getSourceFile(rawFile);
  const catalog = program.getSourceFile(catalogFile);
  const styled = program.getSourceFile(stylesFile);
  const exports = new Map(
    checker
      .getExportsOfModule(checker.getSymbolAtLocation(raw))
      .map((symbol) => [symbol.name, symbol]),
  );
  function unalias(symbol) {
    while (symbol.flags & ts.SymbolFlags.Alias)
      symbol = checker.getAliasedSymbol(symbol);
    return symbol;
  }
  let controls;
  for (const statement of catalog.statements) {
    if (!ts.isVariableStatement(statement)) continue;
    const declaration = statement.declarationList.declarations.find(
      (declaration) => declaration.name.getText(catalog) === 'uiComponents',
    );
    if (!declaration) continue;
    controls = declaration.initializer;
    while (ts.isAsExpression(controls) || ts.isSatisfiesExpression(controls))
      controls = controls.expression;
  }
  if (!controls || !ts.isObjectLiteralExpression(controls))
    throw new Error('uiComponents must be a static object contract');
  const styles = new Map();
  function readStyles(node) {
    if (
      ts.isCallExpression(node) &&
      node.expression.getText(styled) === 'registerComponentStyles'
    ) {
      const [component, sheets] = node.arguments;
      if (
        !ts.isPropertyAccessExpression(component) ||
        !ts.isIdentifier(sheets)
      ) {
        throw new Error(
          'Expected registerComponentStyles(ui.Name, styleFamily)',
        );
      }
      styles.set(component.name.text, sheets.text);
    }
    ts.forEachChild(node, readStyles);
  }
  readStyles(styled);

  return controls.properties.map((property) => {
    if (!ts.isPropertyAssignment(property))
      throw new Error('Catalog entries must have named controls');
    const name = property.name.text;
    const rawName = ts.isPropertyAccessExpression(property.initializer)
      ? property.initializer.name.text
      : name;
    const exported = exports.get(rawName);
    if (!exported) throw new Error(`Missing raw control export: ${rawName}`);
    const symbol = unalias(exported);
    const declaration = symbol.valueDeclaration ?? symbol.declarations?.[0];
    if (!declaration) throw new Error(`Missing source declaration: ${name}`);
    const source = declaration.getSourceFile();
    if (!source.fileName.startsWith(packageRoot + '/'))
      throw new Error(
        `Control ${name} must be owned by package/: ${source.fileName}`,
      );
    const ownerExports = checker.getExportsOfModule(
      checker.getSymbolAtLocation(source),
    );
    const ownerExport =
      ownerExports.find(
        (candidate) =>
          candidate.name === rawName && unalias(candidate) === symbol,
      ) ?? ownerExports.find((candidate) => unalias(candidate) === symbol);
    if (!ownerExport)
      throw new Error(
        `Control ${name} is not publicly exported from its owning module`,
      );
    const sheets = styles.get(rawName);
    if (!sheets)
      throw new Error(`Missing component style registration: ${rawName}`);
    return {
      name,
      slug: slug(name),
      owner: relative(packageRoot, source.fileName)
        .replaceAll('\\', '/')
        .replace(/\.tsx?$/, ''),
      exportName: ownerExport.name,
      styles: sheets,
    };
  });
}

export async function generateComponentControls(
  root = defaultRoot,
  check = false,
) {
  const controls = componentControls(root);
  const output = resolve(root, 'package/component-controls');
  const files = new Map(
    await Promise.all(
      controls.map(async (control) => [
        `${control.slug}.ts`,
        await formatGenerated(
          `${marker}\nimport { ${control.exportName} as Control } from '../${control.owner}';\nimport { registerComponentStyles } from '../core/component-styles';\nimport { ${control.styles} } from '../component-style-families';\n\nexport const ${control.name}: typeof Control =\n  /* @__PURE__ */ registerComponentStyles(Control, ${control.styles});\n`,
          `${control.slug}.ts`,
        ),
      ]),
    ),
  );
  if (new Set(controls.map((control) => control.slug)).size !== controls.length)
    throw new Error('Duplicate component leaf slug');
  const existing = existsSync(output)
    ? readdirSync(output).filter((name) => name.endsWith('.ts'))
    : [];
  const stale = existing.filter((name) => !files.has(name));
  const changed = [...files]
    .filter(
      ([name, content]) =>
        !existsSync(resolve(output, name)) ||
        readFileSync(resolve(output, name), 'utf8') !== content,
    )
    .map(([name]) => name);
  if (check) {
    if (stale.length || changed.length)
      throw new Error(
        `Component controls need regeneration: ${[...changed, ...stale].join(', ')}`,
      );
  } else {
    mkdirSync(output, { recursive: true });
    for (const name of stale) {
      const file = resolve(output, name);
      if (!readFileSync(file, 'utf8').startsWith(marker))
        throw new Error(`Refusing to replace an ungenerated control: ${file}`);
      rmSync(file);
    }
    for (const [name, content] of files)
      writeFileSync(resolve(output, name), content);
  }
  return controls;
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
) {
  const controls = await generateComponentControls(
    defaultRoot,
    process.argv.includes('--check'),
  );
  console.log(
    `Verified ${controls.length} component controls${process.argv.includes('--check') ? '' : ' and generated direct imports'}.`,
  );
}
